import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  label?: string;
  defaultTags?: string[];
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  defaultTags = [],
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const apply = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const add = (next: string[]) => {
    const unique = next.reduce<string[]>((acc, tag) => {
      const trimmed = tag.trim();
      if (trimmed && !acc.includes(trimmed)) acc.push(trimmed);
      return acc;
    }, []);
    apply(unique);
  };

  const remove = (tag: string) => {
    apply(tags.filter((item) => item !== tag));
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '10px',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <label className="jx-label" htmlFor="article-tags">
        {label}
      </label>

      <JxTagInput
        id="article-tags"
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={add}
      />

      {tags.length > 0 ? (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <span role="listitem" key={tag}>
              <JxChip active removable onRemove={() => remove(tag)}>
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      ) : (
        <JxEmptyState
          title="Тегов пока нет"
          message="Добавьте хотя бы один тег, чтобы статью было проще найти."
        />
      )}
    </div>
  );
}

